import Foundation

/// One routable target in the picker. `ref` is the provider's own id for it
/// (a Bear note id, a 15Five person id). The Inbox is synthetic: in capture
/// mode it files to the Bear Inbox note, in triage it keeps the item there.
struct Destination: Codable, Identifiable, Hashable, Sendable {
    enum Kind: String, Codable, Sendable {
        case inbox, project, personal, person, list, agenda, oneOnOne

        var label: String { self == .oneOnOne ? "15Five" : rawValue }
    }

    let provider: ProviderID
    /// nil only for the synthetic Inbox row.
    let ref: String?
    let title: String
    let kind: Kind
    var lastModified: Date?

    /// Provider-qualified, so the same person in Bear and 15Five never collide.
    var id: String { ref.map { "\(provider.rawValue):\($0)" } ?? "inbox" }

    static let inbox = Destination(provider: .bear, ref: nil, title: "Inbox", kind: .inbox)
}

/// Precomputed normalization so per-keystroke ranking allocates nothing.
struct IndexedDestination: Sendable {
    let destination: Destination
    let normalizedTitle: String
    let words: [String]

    init(_ destination: Destination) {
        self.destination = destination
        normalizedTitle = destination.title
            .folding(options: [.caseInsensitive, .diacriticInsensitive], locale: nil)
        words = normalizedTitle
            .split(whereSeparator: { " -/&,".contains($0) })
            .map(String.init)
    }
}
import Foundation

struct RankedDestination: Identifiable, Sendable {
    let destination: Destination
    let score: Double
    var id: String { destination.id }
}

/// Pure per-keystroke ranking over the precomputed index. ~30 items,
/// no allocation-heavy work — comfortably sub-millisecond.
enum DestinationRanker {
    /// `pinned` is the Inbox row: it always occupies row 0 when the query is
    /// empty, so ⏎⏎ means "straight to the Inbox" (capture) or "keep it
    /// there" (triage).
    static func rank(
        indexed: [IndexedDestination],
        query: String,
        usageIndex: [String: Int],
        pinned: Destination?,
        now: Date = Date()
    ) -> [RankedDestination] {
        let trimmed = query.trimmingCharacters(in: .whitespaces)

        if trimmed.isEmpty {
            var top: [RankedDestination] = []
            top.reserveCapacity(indexed.count)
            for item in indexed {
                let score = recencyScore(item.destination, now: now)
                    + mruScore(item.destination, usageIndex)
                top.append(RankedDestination(destination: item.destination, score: score))
            }
            top.sort { $0.score == $1.score ? $0.id < $1.id : $0.score > $1.score }
            if let pinned {
                top.insert(RankedDestination(destination: pinned, score: .infinity), at: 0)
            }
            return top
        }

        let q = trimmed.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: nil)
        var results: [RankedDestination] = []

        if let pinned {
            let pinnedIndexed = IndexedDestination(pinned)
            if let quality = matchQuality(pinnedIndexed, query: q) {
                results.append(RankedDestination(destination: pinned, score: quality + 5))
            }
        }
        for item in indexed {
            guard let quality = matchQuality(item, query: q) else { continue }
            let score = quality
                + recencyScore(item.destination, now: now)
                + mruScore(item.destination, usageIndex)
            results.append(RankedDestination(destination: item.destination, score: score))
        }
        return results.sorted { $0.score == $1.score ? $0.id < $1.id : $0.score > $1.score }
    }

    // MARK: - Scoring

    /// title-prefix 100 > word-boundary prefix 80 > fuzzy subsequence 40 + compactness.
    static func matchQuality(_ item: IndexedDestination, query: String) -> Double? {
        if item.normalizedTitle.hasPrefix(query) { return 100 }
        if item.words.contains(where: { $0.hasPrefix(query) }) { return 80 }
        if let span = subsequenceSpan(of: query, in: item.normalizedTitle) {
            return 40 + 10 * (Double(query.count) / Double(span))
        }
        return nil
    }

    static func recencyScore(_ destination: Destination, now: Date) -> Double {
        guard let modified = destination.lastModified else { return 0 }
        let ageDays = max(0, now.timeIntervalSince(modified) / 86_400)
        return 20 * exp(-ageDays / 14)
    }

    static func mruScore(_ destination: Destination, _ usageIndex: [String: Int]) -> Double {
        guard let index = usageIndex[destination.id] else { return 0 }
        return 15 * exp(-Double(index) / 5)
    }

    /// Greedy subsequence match; returns the span length (last matched index −
    /// first matched index + 1) or nil when `query` is not a subsequence.
    static func subsequenceSpan(of query: String, in text: String) -> Int? {
        guard !query.isEmpty else { return nil }
        var first: Int?
        var last = 0
        var queryIterator = query.makeIterator()
        var needle = queryIterator.next()
        for (offset, char) in text.enumerated() {
            guard let current = needle else { break }
            if char == current {
                if first == nil { first = offset }
                last = offset
                needle = queryIterator.next()
            }
        }
        guard needle == nil, let first else { return nil }
        return last - first + 1
    }
}
import Foundation

struct InboxEntry: Identifiable, Hashable, Sendable {
    /// The header line as found, e.g. "**2026-07-04 09:10**".
    let header: String
    /// Body text without the header, trailing whitespace trimmed. May be empty.
    let body: String
    /// Header + body exactly as they appear in the note — the removal key.
    let exactBlock: String

    var id: String { exactBlock }

    /// The header's timestamp, `2026-07-04 09:10` or date-only `2026-07-04`.
    var datetime: String? {
        guard let match = header.firstMatch(of: /\*\*(\d{4}-\d{2}-\d{2}(?: \d{2}:\d{2})?)\*\*/) else { return nil }
        return String(match.1)
    }
}

/// Splits the Inbox note into capture blocks. Blocks start with a
/// `**YYYY-MM-DD[ HH:mm]**` header (date-only headers exist in the live
/// note); blocks whose header carries a `→` marker (fallback-routed,
/// pending) are skipped, as are the `# Inbox` title and the trailing
/// `#inbox` tag line. Returns oldest-first for triage.
enum InboxParser {
    // Immutable after init; regex just isn't marked Sendable.
    private static nonisolated(unsafe) let headerRegex = /^\*\*\d{4}-\d{2}-\d{2}( \d{2}:\d{2})?\*\*.*$/

    static func isHeader(_ line: Substring) -> Bool {
        line.wholeMatch(of: headerRegex) != nil
    }

    static func parse(_ noteText: String) -> [InboxEntry] {
        let lines = noteText.split(separator: "\n", omittingEmptySubsequences: false)
        var entries: [InboxEntry] = []
        var currentHeader: Substring?
        var currentBody: [Substring] = []

        func flush() {
            guard let header = currentHeader else { return }
            defer {
                currentHeader = nil
                currentBody = []
            }
            // Trim trailing blank lines from the body (they are separators).
            var body = currentBody
            while let last = body.last, last.trimmingCharacters(in: .whitespaces).isEmpty {
                body.removeLast()
            }
            // Skip already-routed blocks (fallback marker in the header).
            guard !header.contains("→") else { return }
            let bodyText = body.joined(separator: "\n")
            let exact = bodyText.isEmpty ? String(header) : header + "\n" + bodyText
            entries.append(InboxEntry(header: String(header), body: bodyText, exactBlock: exact))
        }

        for line in lines {
            if isHeader(line) {
                flush()
                currentHeader = line
            } else if currentHeader != nil {
                // The trailing tag line belongs to the note, not the block.
                if isTagOnlyLine(line) { continue }
                currentBody.append(line)
            }
        }
        flush()

        // Note is newest-on-top; triage goes oldest-first.
        return entries.reversed()
    }

    static func isTagOnlyLine(_ line: Substring) -> Bool {
        let trimmed = line.trimmingCharacters(in: .whitespaces)
        guard trimmed.hasPrefix("#") else { return false }
        return trimmed.split(separator: " ").allSatisfy { $0.hasPrefix("#") && $0.count > 1 }
    }
}

import Foundation
import Observation

/// Stage machine driving the launcher. All transitions are synchronous and
/// in-memory; Bear work happens behind them via CaptureRouter (optimistic).
@MainActor
@Observable
final class LauncherModel {
    enum Mode { case capture, triage }

    enum Stage: Equatable {
        case loading      // triage only: reading the inbox (a few ms)
        case compose      // editing the thought (prefilled in triage)
        case route        // destination picker below the dimmed text
        case done         // triage only: "inbox clear" flash
    }

    let mode: Mode
    private let store: DestinationStore
    private let router: CaptureRouter
    private let bear: BearCLI
    /// Hides the panel. The model decides when; the delegate does the hiding.
    private let onFinish: () -> Void

    private(set) var stage: Stage
    var composeText: String = ""
    var query: String = "" {
        didSet { if query != oldValue { refilter() } }
    }
    private(set) var selectionIndex = 0
    private(set) var ranked: [RankedDestination] = []
    private(set) var lastFilterMS: Double = 0
    private(set) var hint: String?

    // Triage session (immutable snapshot).
    private(set) var entries: [InboxEntry] = []
    private(set) var currentIndex = 0

    init(
        mode: Mode,
        store: DestinationStore,
        router: CaptureRouter,
        bear: BearCLI,
        onFinish: @escaping () -> Void
    ) {
        self.mode = mode
        self.store = store
        self.router = router
        self.bear = bear
        self.onFinish = onFinish
        self.stage = mode == .capture ? .compose : .loading
        if mode == .triage { loadTriageSession() }
    }

    // MARK: - Derived display state

    var counterText: String? {
        guard mode == .triage, !entries.isEmpty, currentIndex < entries.count else { return nil }
        return "\(currentIndex + 1)/\(entries.count)"
    }

    var bannerText: String {
        composeText.isEmpty ? "(empty)" : composeText
    }

    var composePlaceholder: String {
        mode == .capture ? "Capture a thought…" : "(empty)"
    }

    var queryPlaceholder: String {
        let fallback: String
        switch mode {
        case .capture: fallback = "enter → inbox"
        case .triage: fallback = "enter → keep in inbox"
        }
        return "route to…  \(fallback)"
    }

    var hintText: String {
        if let hint { return hint }
        switch (mode, stage) {
        case (.capture, .route): return "↩ route · esc back"
        case (.triage, .compose): return "↩ route · ⇥ skip · ⌘⌫ discard · esc exit"
        case (.triage, .route): return "↩ file · ⇥ skip · ⌘⌫ discard · esc back"
        default: return ""
        }
    }

    /// Empty-query default row. In triage, picking it keeps the item in the
    /// Inbox and moves on.
    private var pinnedDestination: Destination { .inbox }

    // MARK: - Stage transitions

    func submitCompose() {
        let trimmed = composeText.trimmingCharacters(in: .whitespacesAndNewlines)
        switch mode {
        case .capture:
            guard !trimmed.isEmpty else {
                onFinish()
                return
            }
        case .triage:
            break // empty entries can still be routed/discarded
        }
        beginRouting()
    }

    private func beginRouting() {
        query = ""
        hint = nil
        refilter()
        stage = .route
    }

    func submitRoute() {
        guard selectionIndex < ranked.count else {
            if mode == .triage { advance() }
            return
        }
        let destination = ranked[selectionIndex].destination
        let text = composeText.trimmingCharacters(in: .whitespacesAndNewlines)

        switch mode {
        case .capture:
            if destination.kind == .inbox {
                router.captureToInbox(text: text)
            } else {
                router.file(text: text, to: destination)
            }
            onFinish()
        case .triage:
            let entry = entries[currentIndex]
            router.triageRoute(entry: entry, editedText: text, to: destination)
            advance()
        }
    }

    /// Route stage with no rows at all (a query that matches nothing): Enter
    /// skips in triage and does nothing in capture.
    var routeHasRows: Bool { !ranked.isEmpty }

    func escape() {
        switch stage {
        case .route:
            stage = .compose
        case .compose, .loading, .done:
            onFinish()
        }
    }

    func skip() {
        guard mode == .triage else { return }
        advance()
    }

    func discard() {
        guard mode == .triage, currentIndex < entries.count else { return }
        router.triageDiscard(entry: entries[currentIndex])
        advance()
    }

    func moveSelection(_ delta: Int) {
        guard !ranked.isEmpty else { return }
        selectionIndex = max(0, min(ranked.count - 1, selectionIndex + delta))
    }

    func refilter() {
        let start = CFAbsoluteTimeGetCurrent()
        ranked = DestinationRanker.rank(
            indexed: store.indexed,
            query: query,
            usageIndex: store.usageIndex,
            pinned: pinnedDestination
        )
        lastFilterMS = (CFAbsoluteTimeGetCurrent() - start) * 1000
        selectionIndex = 0
    }

    // MARK: - Triage session

    private func loadTriageSession() {
        Task { [weak self] in
            guard let self else { return }
            do {
                let content = try await bear.readNote(id: DestinationStore.inboxNoteId).content
                let parsed = InboxParser.parse(content)
                self.entries = parsed
                if parsed.isEmpty {
                    self.finishTriage()
                } else {
                    self.currentIndex = 0
                    self.composeText = parsed[0].body
                    self.stage = .compose
                }
            } catch {
                Notify.failure("Could not read the Inbox note: \(error)")
                self.onFinish()
            }
        }
    }

    private func advance() {
        hint = nil
        currentIndex += 1
        guard currentIndex < entries.count else {
            finishTriage()
            return
        }
        composeText = entries[currentIndex].body
        query = ""
        stage = .compose
    }

    private func finishTriage() {
        stage = .done
        Task { [weak self] in
            try? await Task.sleep(for: .milliseconds(500))
            self?.onFinish()
        }
    }
}
import Foundation

/// Orchestrates all capture writes. Callers are synchronous and optimistic —
/// the panel hides / triage advances immediately; every method runs its work
/// in a fire-and-forget Task. Destinations are written by their provider; the
/// Inbox stays Bear's. Invariant: a capture is NEVER lost — any failure
/// degrades to the x-callback Inbox write with a marker plus a notification.
@MainActor
final class CaptureRouter {
    private let bear: BearCLI
    private let store: DestinationStore

    init(bear: BearCLI, store: DestinationStore) {
        self.bear = bear
        self.store = store
    }

    private static let datetimeFormatter: DateFormatter = {
        let f = DateFormatter()
        f.locale = Locale(identifier: "en_US_POSIX")
        f.dateFormat = "yyyy-MM-dd HH:mm"
        return f
    }()

    // MARK: - Public entry points (all optimistic)

    /// Plain capture to the Inbox note, prepended under the H1 — same block
    /// format the x-callback template produced.
    func captureToInbox(text: String, timestamp: Date = Date()) {
        let block = "**\(Self.datetimeFormatter.string(from: timestamp))**\n\(text)"
        let inboxId = DestinationStore.inboxNoteId
        Task {
            do {
                try await bear.casEdit(noteId: inboxId) { content in
                    Self.prepending(block: block, to: content)
                }
                Self.logRouting(source: "capture", text: text, destination: "Inbox", noteId: inboxId)
            } catch {
                // Fallback: the original x-callback path.
                DailyCapture.send(text)
                Notify.failure("Inbox write via bearcli failed — sent via Bear URL instead. \(error)")
            }
        }
    }

    /// Routed capture: lands verbatim in the destination note's section.
    func file(text: String, to destination: Destination, timestamp: Date = Date()) {
        store.recordUsage(destination)
        let datetime = Self.datetimeFormatter.string(from: timestamp)
        Task {
            await fileAndVerify(text: text, to: destination, datetime: datetime, source: "capture")
        }
    }

    /// Triage decision: file the (possibly edited) text under its original
    /// Inbox timestamp, then remove the block from the Inbox. The Inbox row
    /// means "keep it there", so nothing moves.
    func triageRoute(entry: InboxEntry, editedText: String, to destination: Destination) {
        guard destination.kind != .inbox else { return }
        store.recordUsage(destination)
        let datetime = entry.datetime ?? Self.datetimeFormatter.string(from: Date())
        Task {
            let filed = await fileAndVerify(
                text: editedText,
                to: destination,
                datetime: datetime,
                source: "triage"
            )
            guard filed else { return } // fallback already notified; block stays put
            await removeInboxBlock(entry)
        }
    }

    /// Triage discard: remove the block, file nothing.
    func triageDiscard(entry: InboxEntry) {
        Task {
            await removeInboxBlock(entry)
            Self.logRouting(source: "discard", text: entry.body, destination: "-", noteId: DestinationStore.inboxNoteId)
        }
    }

    // MARK: - Filing

    @discardableResult
    private func fileAndVerify(
        text: String,
        to destination: Destination,
        datetime: String,
        source: String
    ) async -> Bool {
        let label = Self.markerLabel(destination)
        guard let provider = store.provider(destination.provider), destination.provider.isEnabled else {
            fallbackToInbox(text: text, destination: label,
                            reason: "\(destination.provider.displayName) is switched off")
            return false
        }
        do {
            try await provider.file(text: text, datetime: datetime, to: destination, requestID: UUID())
            Self.logRouting(source: source, text: text, destination: label, noteId: destination.ref)
            return true
        } catch {
            fallbackToInbox(text: text, destination: label, reason: String(describing: error))
            return false
        }
    }

    /// The title the `review-captures` skill routes by; non-Bear destinations
    /// name their system so the parked capture says where it was going.
    nonisolated static func markerLabel(_ destination: Destination) -> String {
        destination.provider == .bear
            ? destination.title
            : "\(destination.title) (\(destination.provider.displayName))"
    }

    private func removeInboxBlock(_ entry: InboxEntry) async {
        do {
            try await bear.casEdit(noteId: DestinationStore.inboxNoteId) { content in
                Self.removingBlock(entry.exactBlock, from: content)
            }
        } catch {
            Notify.failure("Could not remove the inbox block — it may reappear in triage. \(error)")
        }
    }

    private func fallbackToInbox(text: String, destination: String, reason: String) {
        DailyCapture.send(text, marker: destination)
        Notify.failure("Filing to \(destination) failed — capture parked in Inbox with a marker. \(reason)")
        Self.logRouting(source: "fallback", text: text, destination: destination, noteId: nil)
    }

    // MARK: - Pure text transforms

    /// Prepend a capture block directly under the note's H1 (or at the very
    /// top when there is none), blank-line separated from what follows.
    nonisolated static func prepending(block: String, to content: String) -> String {
        if content.hasPrefix("# "), let firstBreak = content.firstIndex(of: "\n") {
            let head = content[..<firstBreak]
            let rest = content[content.index(after: firstBreak)...]
            return "\(head)\n\(block)\n\n\(rest)"
        }
        return "\(block)\n\n\(content)"
    }

    /// Exact-string block removal. nil = not found (idempotent no-op:
    /// already removed by an earlier attempt or by hand).
    nonisolated static func removingBlock(_ block: String, from content: String) -> String? {
        for pattern in [block + "\n\n", block + "\n"] {
            if let range = content.range(of: pattern) {
                return collapseBlankRuns(content.replacingCharacters(in: range, with: ""))
            }
        }
        if let range = content.range(of: block) {
            return collapseBlankRuns(content.replacingCharacters(in: range, with: ""))
        }
        return nil
    }

    nonisolated private static func collapseBlankRuns(_ text: String) -> String {
        text.replacing(/\n{3,}/, with: "\n\n")
    }

    // MARK: - Routing log

    nonisolated private static var logURL: URL {
        FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Logs/Capture/routings.jsonl")
    }

    nonisolated static func logRouting(source: String, text: String, destination: String, noteId: String?) {
        struct Record: Codable {
            let ts: String
            let source: String
            let text: String
            let destination: String
            let noteId: String?
        }
        let record = Record(
            ts: ISO8601DateFormatter().string(from: Date()),
            source: source, text: text, destination: destination, noteId: noteId
        )
        guard var data = try? JSONEncoder().encode(record) else { return }
        data.append(Data("\n".utf8))
        let url = logURL
        try? FileManager.default.createDirectory(
            at: url.deletingLastPathComponent(), withIntermediateDirectories: true
        )
        if let handle = try? FileHandle(forWritingTo: url) {
            defer { try? handle.close() }
            _ = try? handle.seekToEnd()
            try? handle.write(contentsOf: data)
        } else {
            try? data.write(to: url)
        }
    }
}

import Foundation

/// Files into the Bear second brain through bearcli. Destinations are notes
/// with a routable flat type tag; a capture lands verbatim as one line in the
/// note's section, matching the `review-captures` skill.
struct BearProvider: DestinationProvider {
    let bear: BearCLI
    var id: ProviderID { .bear }

    func listDestinations() async throws -> [Destination] {
        Self.destinations(from: try await bear.listNotes())
    }

    func file(text: String, datetime: String, to destination: Destination, requestID: UUID) async throws {
        guard let noteId = destination.ref else { throw BearCLI.Failure.badOutput("no note for \(destination.title)") }
        let line = Self.captureLine(text: text, datetime: datetime)
        try await bear.casEdit(noteId: noteId) { content in
            Self.inserting(line, into: content, kind: destination.kind)
        }
    }

    // MARK: - Destinations (pure, testable)

    /// One destination per note carrying a routable type tag, most recently
    /// modified first. The Inbox note is excluded: it is the synthetic row.
    nonisolated static func destinations(from notes: [BearCLI.NoteMeta]) -> [Destination] {
        notes
            .compactMap { note -> Destination? in
                guard note.id != DestinationStore.inboxNoteId,
                      !note.title.isEmpty,
                      let kind = kind(forTags: note.tags) else { return nil }
                return Destination(provider: .bear, ref: note.id, title: note.title,
                                   kind: kind, lastModified: note.modified)
            }
            .sorted { ($0.lastModified ?? .distantPast) > ($1.lastModified ?? .distantPast) }
    }

    /// `#archive`, `#unsorted`, `#reference` and the rest are never routable.
    nonisolated static func kind(forTags tags: [String]) -> Destination.Kind? {
        for raw in tags {
            switch raw.hasPrefix("#") ? String(raw.dropFirst()) : raw {
            case "project": return .project
            case "personal": return .personal
            case "person": return .person
            case "list": return .list
            case "agenda": return .agenda
            default: continue
            }
        }
        return nil
    }

    // MARK: - Note format (pure, testable)

    /// Agendas collect topics; every other note collects captures.
    nonisolated static func section(for kind: Destination.Kind) -> String {
        kind == .agenda ? "## Topics" : "## Captures"
    }

    /// Project, personal and person notes keep captures newest first. Lists
    /// and agendas are running lists, appended at the bottom.
    nonisolated static func newestFirst(_ kind: Destination.Kind) -> Bool {
        [.project, .personal, .person].contains(kind)
    }

    /// `- **2026-07-04 09:12**: text`, the second brain's capture line, with
    /// multi-line bodies indented under the bullet.
    nonisolated static func captureLine(text: String, datetime: String) -> String {
        let lines = text.split(separator: "\n", omittingEmptySubsequences: false)
        return "- **\(datetime)**: " + lines.joined(separator: "\n  ")
    }

    /// Insert `line` into the kind's section: at the top when the kind keeps
    /// newest first, at the bottom otherwise. A missing section is created
    /// above the trailing tag line, the only place the skills expect it.
    nonisolated static func inserting(_ line: String, into content: String, kind: Destination.Kind) -> String {
        let heading = section(for: kind)
        guard let headingRange = sectionHeadingRange(heading, in: content) else {
            let section = "\(heading)\n\n\(line)"
            if let tagStart = trailingTagBlockStart(of: content) {
                let head = trimmingTrailingNewlines(String(content[..<tagStart]))
                return head + "\n\n" + section + "\n\n" + content[tagStart...]
            }
            return trimmingTrailingNewlines(content) + "\n\n" + section + "\n"
        }

        let bodyStart = headingRange.upperBound
        let afterHeading = content[bodyStart...]
        var bodyEnd = afterHeading.range(of: "\n## ")?.lowerBound ?? content.endIndex
        if let tagStart = trailingTagBlockStart(of: content), tagStart > bodyStart, tagStart < bodyEnd {
            bodyEnd = tagStart
        }
        let body = String(content[bodyStart..<bodyEnd])
            .trimmingCharacters(in: .newlines)
        let newBody = body.isEmpty ? line : (newestFirst(kind) ? line + "\n" + body : body + "\n" + line)
        // The tail starts with "\n## " (next heading), a tag line, or is empty.
        let tail = content[bodyEnd...]
        let separator = tail.isEmpty || tail.hasPrefix("\n") ? "\n" : "\n\n"
        return content[..<bodyStart] + "\n\n" + newBody + separator + tail
    }

    /// The heading line, matched whole so `## Captures` never matches a
    /// longer heading that merely starts with it.
    nonisolated private static func sectionHeadingRange(_ heading: String, in content: String) -> Range<String.Index>? {
        var search = content.startIndex..<content.endIndex
        while let range = content.range(of: heading, range: search) {
            let atLineStart = range.lowerBound == content.startIndex
                || content[content.index(before: range.lowerBound)] == "\n"
            let rest = content[range.upperBound...].prefix { $0 != "\n" }
            if atLineStart && rest.allSatisfy(\.isWhitespace) {
                return range.lowerBound..<content.index(range.upperBound, offsetBy: rest.count)
            }
            search = range.upperBound..<content.endIndex
        }
        return nil
    }

    nonisolated private static func trimmingTrailingNewlines(_ text: String) -> String {
        var trimmed = text
        while trimmed.hasSuffix("\n") { trimmed.removeLast() }
        return trimmed
    }

    /// Index of the first line of the trailing tag-only block (Bear keeps
    /// `#project`-style tags as the last line(s) of a note), or nil.
    nonisolated private static func trailingTagBlockStart(of content: String) -> String.Index? {
        var lines: [(line: Substring, start: String.Index)] = []
        var lineStart = content.startIndex
        for index in content.indices {
            if content[index] == "\n" {
                lines.append((content[lineStart..<index], lineStart))
                lineStart = content.index(after: index)
            }
        }
        lines.append((content[lineStart...], lineStart))

        var tagBlockStart: String.Index?
        for (line, start) in lines.reversed() {
            let trimmed = line.trimmingCharacters(in: .whitespaces)
            if trimmed.isEmpty {
                if tagBlockStart == nil { continue } // trailing blank lines
                break
            }
            if InboxParser.isTagOnlyLine(line) {
                tagBlockStart = start
            } else {
                break
            }
        }
        return tagBlockStart
    }
}
