import Observation

/// In-memory destination list backing the picker, merged across enabled
/// providers. Loaded synchronously from per-provider JSON caches at launch
/// (the picker is never empty), refreshed asynchronously at launch, on every
/// panel show, and on demand. A provider that fails keeps its cached rows.
@MainActor
@Observable
final class DestinationStore {
    nonisolated static let inboxNoteIdKey = "inboxNoteID"
    nonisolated static let defaultInboxNoteId = "E01000CB-BE7D-4FCB-8340-BBE23A4569B9"

    struct ProviderState {
        var destinations: [Destination] = []
        var lastRefresh: Date?
        var lastError: String?
        var refreshing = false
    }

    let providers: [any DestinationProvider]
    private(set) var states: [ProviderID: ProviderState] = [:]
    private(set) var destinations: [Destination] = []
    private(set) var indexed: [IndexedDestination] = []

    /// Most-recently-used destination ids, most recent first, unique.
    private(set) var usage: [String] = []
    private(set) var usageIndex: [String: Int] = [:]

    init(providers: [any DestinationProvider]) {
        self.providers = providers
    }

    nonisolated static var inboxNoteId: String {
        let stored = UserDefaults.standard.string(forKey: inboxNoteIdKey)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return stored.isEmpty ? defaultInboxNoteId : stored
    }

    func provider(_ id: ProviderID) -> (any DestinationProvider)? {
        providers.first { $0.id == id }
    }

    func state(_ id: ProviderID) -> ProviderState {
        states[id] ?? ProviderState()
    }

    // MARK: - Cache

    private static var supportDir: URL {
        FileManager.default.urls(for: .applicationSupportDirectory, in: .userDomainMask)[0]
            .appendingPathComponent("Capture", isDirectory: true)
    }
    private static func cacheURL(_ id: ProviderID) -> URL {
        supportDir.appendingPathComponent("destinations-\(id.rawValue).json")
    }
    // v3: ids became provider-qualified (`bear:<note id>`).
    private static var usageURL: URL { supportDir.appendingPathComponent("usage-v3.json") }

    func loadCache() {
        try? FileManager.default.createDirectory(at: Self.supportDir, withIntermediateDirectories: true)
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        for provider in providers {
            if let data = try? Data(contentsOf: Self.cacheURL(provider.id)),
               let cached = try? decoder.decode([Destination].self, from: data) {
                states[provider.id, default: ProviderState()].destinations = cached
            }
        }
        if let data = try? Data(contentsOf: Self.usageURL),
           let ids = try? decoder.decode([String].self, from: data) {
            usage = ids
            rebuildUsageIndex()
        }
        merge()
    }

    private func persistCache(_ id: ProviderID) {
        let encoder = JSONEncoder()
        encoder.dateEncodingStrategy = .iso8601
        if let data = try? encoder.encode(state(id).destinations) {
            try? data.write(to: Self.cacheURL(id), options: .atomic)
        }
    }

    func recordUsage(_ destination: Destination) {
        usage.removeAll { $0 == destination.id }
        usage.insert(destination.id, at: 0)
        if usage.count > 50 { usage.removeLast(usage.count - 50) }
        rebuildUsageIndex()
        if let data = try? JSONEncoder().encode(usage) {
            try? data.write(to: Self.usageURL, options: .atomic)
        }
    }

    private func rebuildUsageIndex() {
        usageIndex = Dictionary(uniqueKeysWithValues: usage.enumerated().map { ($1, $0) })
    }

    // MARK: - Refresh

    func refresh() {
        for provider in providers where provider.id.isEnabled {
            refresh(provider)
        }
        merge() // drops rows of providers switched off since the last refresh
    }

    private func refresh(_ provider: any DestinationProvider) {
        let id = provider.id
        guard !state(id).refreshing else { return }
        states[id, default: ProviderState()].refreshing = true
        Task { [weak self] in
            do {
                let fresh = try await provider.listDestinations()
                guard let self else { return }
                self.states[id, default: ProviderState()].destinations = fresh
                self.states[id]?.lastRefresh = Date()
                self.states[id]?.lastError = nil
                self.persistCache(id)
                self.merge()
            } catch {
                self?.states[id, default: ProviderState()].lastError = String(describing: error)
            }
            self?.states[id]?.refreshing = false
        }
    }

    private func merge() {
        destinations = Self.merged(states.filter { $0.key.isEnabled }.map(\.value.destinations))
        indexed = destinations.map(IndexedDestination.init)
    }

    /// Most recently modified first across all providers.
    nonisolated static func merged(_ lists: [[Destination]]) -> [Destination] {
        lists.flatMap { $0 }
            .sorted { ($0.lastModified ?? .distantPast) > ($1.lastModified ?? .distantPast) }
    }
}

import SwiftUI

struct LauncherView: View {
    @Bindable var model: LauncherModel

    /// Resolved by the caller, not read from the environment. `LauncherPanel`
    /// pins its own appearance to the theme's darkness, so `colorScheme` in
    /// here reports the theme back at us rather than the system setting.
    let theme: Theme
    let onHeightChange: (CGFloat) -> Void

    private enum Field { case compose, query }
    @FocusState private var focus: Field?

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            switch model.stage {
            case .loading:
                statusRow("loading…")
            case .compose:
                composeStage
            case .route:
                routeStage
            case .done:
                statusRow("inbox clear")
            }
        }
        .frame(width: LauncherPanel.width, alignment: .leading)
        .background(theme.background)
        .clipShape(RoundedRectangle(cornerRadius: Theme.cornerRadius, style: .continuous))
        .fixedSize(horizontal: false, vertical: true)
        .background(
            GeometryReader { geom in
                Color.clear
                    .preference(key: HeightKey.self, value: geom.size.height)
            }
        )
        .onPreferenceChange(HeightKey.self) { newHeight in
            onHeightChange(newHeight)
        }
        .onExitCommand { model.escape() }
        .onAppear { focus = .compose }
        .onChange(of: model.stage) {
            let target: Field? = model.stage == .route ? .query : .compose
            DispatchQueue.main.async { focus = target }
        }
    }

    // MARK: - Compose stage

    private var composeStage: some View {
        HStack(alignment: .top, spacing: 12) {
            TextField("", text: $model.composeText, axis: .vertical)
                .textFieldStyle(.plain)
                .font(theme.font(size: 22).weight(.light))
                .foregroundStyle(theme.foreground)
                .tint(theme.accent)
                .lineLimit(1...5)
                .focused($focus, equals: .compose)
                .placeholder(model.composePlaceholder,
                             when: model.composeText.isEmpty,
                             theme: theme, size: 22)
                .onKeyPress(phases: .down) { press in
                    handleComposeKey(press)
                }
            if let counter = model.counterText {
                Text(counter)
                    .font(theme.font(size: 12))
                    .foregroundStyle(theme.dim)
                    .padding(.top, 6)
            }
        }
        .padding(.horizontal, 20)
        .padding(.top, 18)
        .padding(.bottom, model.mode == .triage ? 8 : 18)
        .overlay(alignment: .bottomLeading) {
            if model.mode == .triage {
                hintRow.padding(.leading, 20).padding(.bottom, -8)
            }
        }
        .padding(.bottom, model.mode == .triage ? 14 : 0)
    }

    private func handleComposeKey(_ press: KeyPress) -> KeyPress.Result {
        if press.key == .return {
            if press.modifiers.contains(.shift) {
                model.composeText.append("\n")
                return .handled
            }
            model.submitCompose()
            return .handled
        }
        if model.mode == .triage {
            if press.key == .tab {
                model.skip()
                return .handled
            }
            if isDiscardChord(press) {
                model.discard()
                return .handled
            }
        }
        return .ignored
    }

    /// ⌘⌫ — matched on the raw characters too: the backspace key reports
    /// 0x7F or 0x08 depending on the path, and missing it here lets the
    /// system's "delete to start of line" binding eat the chord instead.
    private func isDiscardChord(_ press: KeyPress) -> Bool {
        guard press.modifiers.contains(.command) else { return false }
        if press.key == .delete { return true }
        return press.characters.contains("\u{7F}") || press.characters.contains("\u{08}")
    }

    // MARK: - Route stage

    private var routeStage: some View {
        VStack(alignment: .leading, spacing: 0) {
            HStack(alignment: .top, spacing: 12) {
                Text(model.bannerText)
                    .font(theme.font(size: 13))
                    .foregroundStyle(theme.secondary)
                    .lineLimit(model.mode == .triage ? 4 : 2)
                Spacer(minLength: 8)
                if let counter = model.counterText {
                    Text(counter)
                        .font(theme.font(size: 12))
                        .foregroundStyle(theme.dim)
                }
            }
            .padding(.horizontal, 20)
            .padding(.top, 16)
            .padding(.bottom, 10)

            HStack(spacing: 10) {
                TextField("", text: $model.query)
                    .textFieldStyle(.plain)
                    .font(theme.font(size: 22).weight(.light))
                    .foregroundStyle(theme.foreground)
                    .tint(theme.accent)
                    .focused($focus, equals: .query)
                    .placeholder(model.queryPlaceholder,
                                 when: model.query.isEmpty,
                                 theme: theme, size: 22)
                    .onKeyPress(.upArrow) {
                        model.moveSelection(-1)
                        return .handled
                    }
                    .onKeyPress(.downArrow) {
                        model.moveSelection(1)
                        return .handled
                    }
                    .onKeyPress(phases: .down) { press in
                        handleQueryKey(press)
                    }
                Text(String(format: "%.1fms", model.lastFilterMS))
                    .font(theme.font(size: 11))
                    .foregroundStyle(theme.dim)
            }
            .padding(.horizontal, 20)
            .padding(.bottom, 10)

            // Full bleed, no inset — Gyors' query/list separator.
            Divider().opacity(0.3)

            DestinationListView(
                ranked: model.ranked,
                selectionIndex: model.selectionIndex,
                theme: theme
            )

            hintRow
                .padding(.horizontal, 20)
                .padding(.top, 6)
                .padding(.bottom, 12)
        }
    }

    private func handleQueryKey(_ press: KeyPress) -> KeyPress.Result {
        if press.key == .return {
            model.submitRoute()
            return .handled
        }
        if model.mode == .triage {
            if press.key == .tab {
                model.skip()
                return .handled
            }
            if isDiscardChord(press) {
                model.discard()
                return .handled
            }
        }
        return .ignored
    }

    // MARK: - Shared bits

    private var hintRow: some View {
        Text(model.hintText)
            .font(theme.font(size: 11))
            .foregroundStyle(theme.dim)
    }

    private func statusRow(_ text: String) -> some View {
        Text(text)
            .font(theme.font(size: 16))
            .foregroundStyle(theme.secondary)
            .padding(.horizontal, 20)
            .padding(.vertical, 24)
    }
}

private extension View {
    /// Own the placeholder instead of using `TextField(prompt:)`. SwiftUI
    /// overrides the prompt's `foregroundColor` with its own control styling,
    /// so a themed prompt renders at the system placeholder tone regardless of
    /// what we pass — too dark on Ember (Charles, 2026-08-21).
    func placeholder(_ text: String, when visible: Bool, theme: Theme, size: CGFloat) -> some View {
        overlay(alignment: .topLeading) {
            if visible {
                Text(text)
                    .font(theme.font(size: size).weight(.light))
                    .foregroundStyle(theme.secondary)
                    .allowsHitTesting(false)
            }
        }
    }
}

private struct HeightKey: PreferenceKey {
    static let defaultValue: CGFloat = 0
    static func reduce(value: inout CGFloat, nextValue: () -> CGFloat) {
        value = nextValue()
    }
}
import SwiftUI

/// Fixed-viewport destination list: always `Theme.listRows` rows tall so the
/// panel never resizes while filtering; unfilled rows stay blank. Selection is
/// a flat full-bleed accent wash — no radius, no inset (Gyors' ResultRow).
struct DestinationListView: View {
    let ranked: [RankedDestination]
    let selectionIndex: Int
    let theme: Theme

    var body: some View {
        ScrollViewReader { proxy in
            ScrollView {
                rows
            }
            .frame(height: CGFloat(Theme.listRows) * Theme.rowHeight)
            .onChange(of: selectionIndex) { _, newIndex in
                proxy.scrollTo(newIndex)
            }
            .onChange(of: ranked.count) {
                proxy.scrollTo(0, anchor: .top)
            }
        }
    }

    var rows: some View {
        VStack(spacing: 0) {
            ForEach(Array(ranked.enumerated()), id: \.element.id) { index, item in
                row(item.destination, selected: index == selectionIndex)
                    .id(index)
            }
        }
    }

    private func row(_ destination: Destination, selected: Bool) -> some View {
        HStack(spacing: 8) {
            Text(destination.title)
                .font(theme.font(size: 14).weight(.medium))
                .foregroundStyle(theme.foreground)
                .lineLimit(1)
            Spacer(minLength: 8)
            let chip = theme.chip(for: destination.kind)
            Text(destination.kind.label)
                .font(theme.font(size: 11).weight(.semibold))
                .foregroundStyle(chip.text)
                .padding(.horizontal, 6)
                .padding(.vertical, 2)
                .background(
                    RoundedRectangle(cornerRadius: 5, style: .continuous)
                        .fill(LinearGradient(
                            colors: [chip.fillTop, chip.fillBottom],
                            startPoint: .top, endPoint: .bottom
                        ))
                )
        }
        // One 20pt gutter, same as the query row above, so the leaf name lines
        // up with the typed text. No outer padding: the fill must reach both
        // panel edges.
        .padding(.horizontal, 20)
        .frame(height: Theme.rowHeight)
        .background(selected ? theme.selectionBackground : Color.clear)
        .contentShape(Rectangle())
    }
}
import Foundation

/// All Bear I/O goes through this actor, via the `bearcli` binary bundled
/// inside Bear.app. Reads are plain subcommands; every write is a CAS
/// (compare-and-swap) `overwrite --base <hash>` so a concurrent change by
/// Bear.app rejects the write and we re-read and retry. Never touch Bear's
/// SQLite directly.
actor BearCLI {
    struct NoteMeta: Codable, Sendable {
        let id: String
        let title: String
        let tags: [String]
        let modified: Date?
    }

    struct NoteRead: Codable, Sendable {
        let hash: String
        let content: String
    }

    enum Failure: Error, CustomStringConvertible {
        case launchFailed(String)
        case exit(code: Int32, stderr: String)
        case badOutput(String)
        case casConflictPersisted(noteId: String)

        var description: String {
            switch self {
            case .launchFailed(let msg): "bearcli launch failed: \(msg)"
            case .exit(let code, let stderr): "bearcli exit \(code): \(stderr.trimmingCharacters(in: .whitespacesAndNewlines))"
            case .badOutput(let msg): "bearcli unexpected output: \(msg)"
            case .casConflictPersisted(let noteId): "bearcli CAS conflict persisted on note \(noteId)"
            }
        }
    }

    static let defaultPath = "/Applications/Bear.app/Contents/MacOS/bearcli"
    static let pathKey = "bearcliPath"

    private static var cliPath: String {
        let stored = UserDefaults.standard.string(forKey: pathKey)?
            .trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
        return stored.isEmpty ? defaultPath : stored
    }

    private let decoder: JSONDecoder = {
        let d = JSONDecoder()
        d.dateDecodingStrategy = .iso8601
        return d
    }()

    /// Logged once at launch so a Bear update changing the CLI surface is visible.
    func version() async throws -> String {
        let data = try await run(["--version"])
        return String(decoding: data, as: UTF8.self).trimmingCharacters(in: .whitespacesAndNewlines)
    }

    func listNotes() async throws -> [NoteMeta] {
        let data = try await run(["list", "--format", "json", "--fields", "id,title,tags,modified"])
        do {
            return try decoder.decode([NoteMeta].self, from: data)
        } catch {
            throw Failure.badOutput("list decode: \(error)")
        }
    }

    /// Single call returns hash + content together — the atomic CAS read.
    ///
    /// `cat --format json`, not `show --fields hash,content`: bearcli 2.9.x
    /// dropped `hash` from `show`'s field set (it now errors with "Unknown
    /// field: hash"), and a whole-note `cat` is the only source of the hash
    /// that `overwrite --base` wants.
    func readNote(id: String) async throws -> NoteRead {
        let data = try await run(["cat", id, "--format", "json"])
        do {
            return try decoder.decode(NoteRead.self, from: data)
        } catch {
            throw Failure.badOutput("cat decode: \(error)")
        }
    }

    /// Read → transform → hash-guarded overwrite. `transform` returning nil
    /// means "nothing to do" (idempotent no-op). Any rejected write re-reads
    /// and retries; content goes via stdin so no escape mangling.
    func casEdit(noteId: String, transform: @Sendable (String) -> String?) async throws {
        var lastError: Failure?
        for _ in 0..<3 {
            let note = try await readNote(id: noteId)
            guard let newContent = transform(note.content) else { return }
            do {
                _ = try await run(
                    ["overwrite", noteId, "--base", note.hash],
                    stdin: Data(newContent.utf8)
                )
                return
            } catch let failure as Failure {
                if case .exit(1, _) = failure {
                    lastError = failure // likely CAS rejection — re-read and retry
                    continue
                }
                throw failure
            }
        }
        throw lastError ?? Failure.casConflictPersisted(noteId: noteId)
    }

    /// Creates a note from raw content (title derived from the first heading,
    /// tags from #hashtags). Returns the new note id.
    func createNote(content: String) async throws -> String {
        let data = try await run(["create", "--format", "json"], stdin: Data(content.utf8))
        struct Created: Codable { let id: String }
        do {
            return try decoder.decode(Created.self, from: data).id
        } catch {
            throw Failure.badOutput("create decode: \(error)")
        }
    }

    private func run(_ args: [String], stdin: Data? = nil) async throws -> Data {
        let path = Self.cliPath
        return try await withCheckedThrowingContinuation { continuation in
            DispatchQueue.global(qos: .userInitiated).async {
                let process = Process()
                process.executableURL = URL(fileURLWithPath: path)
                process.arguments = args
                let out = Pipe()
                let err = Pipe()
                process.standardOutput = out
                process.standardError = err

                let input: Pipe?
                if stdin != nil {
                    let pipe = Pipe()
                    process.standardInput = pipe
                    input = pipe
                } else {
                    process.standardInput = FileHandle.nullDevice
                    input = nil
                }

                do {
                    try process.run()
                } catch {
                    continuation.resume(throwing: Failure.launchFailed(error.localizedDescription))
                    return
                }

                if let stdin, let input {
                    input.fileHandleForWriting.write(stdin)
                    try? input.fileHandleForWriting.close()
                }

                let outData = out.fileHandleForReading.readDataToEndOfFile()
                let errData = err.fileHandleForReading.readDataToEndOfFile()
                process.waitUntilExit()

                if process.terminationStatus == 0 {
                    continuation.resume(returning: outData)
                } else {
                    continuation.resume(throwing: Failure.exit(
                        code: process.terminationStatus,
                        stderr: String(decoding: errData, as: UTF8.self)
                    ))
                }
            }
        }
    }
}

