// 1. Tag-name queries list every note of that kind.
for q in ["project", "list", "person", "personal", "agenda", "proj"] {
    let ranked = DestinationRanker.rank(indexed: indexed, query: q, usageIndex: [:], pinned: .inbox)
    let kinds = Dictionary(grouping: ranked, by: { $0.destination.kind.rawValue }).mapValues(\.count)
    let top = ranked.prefix(4).map { "\($0.destination.title) [\($0.destination.kind.rawValue)]" }
    print("q=\(q) ->", kinds, "| top:", top)
}
let wantKinds: [(String, Destination.Kind)] = [("project", .project), ("list", .list), ("person", .person)]
for (q, kind) in wantKinds {
    let ranked = DestinationRanker.rank(indexed: indexed, query: q, usageIndex: [:], pinned: .inbox)
    let all = dests.filter { $0.kind == kind }.count
    check(ranked.filter { $0.destination.kind == kind }.count == all, "\(q) misses some \(kind)")
}
let personRanked = DestinationRanker.rank(indexed: indexed, query: "person", usageIndex: [:], pinned: .inbox)
if let firstPersonal = personRanked.firstIndex(where: { $0.destination.kind == .personal }),
   let lastPerson = personRanked.lastIndex(where: { $0.destination.kind == .person && !$0.destination.title.lowercased().hasPrefix("person") }) {
    check(lastPerson < firstPersonal, "person: a personal note outranks a person")
}

// 2. Every list parses, and removing each item in memory removes exactly that item.
for list in dests where list.kind == .list {
    let content = try await bear.readNote(id: list.ref!).content
    let entries = ListParser.parse(content)
    let stamped = entries.filter { $0.datetime != nil }.count
    print("\(list.title): \(entries.count) items, \(stamped) stamped")
    if let e = entries.first { print("   first body: \(e.body.prefix(70).replacingOccurrences(of: "\n", with: "⏎")) | dt=\(e.datetime ?? "-")") }
    for e in entries {
        guard let after = CaptureRouter.removingLines(e.exactBlock, from: content) else { check(false, "\(list.title): not found"); continue }
        let left = ListParser.parse(after)
        check(left.count == entries.count - 1, "\(list.title): removal changed count by \(entries.count - left.count)")
        check(after.hasSuffix(content.hasSuffix("\n") ? "#list\n" : "#list") || !content.contains("#list"), "\(list.title): tag line damaged")
        check(!after.contains("\n\n\n"), "\(list.title): triple newline")
    }
}

